sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Our_Crazy_Aunts dbr:Dearest_(2014_film) }

  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  OPTIONAL { ?director dbp:birthDate ?birthDate1 . }
  OPTIONAL { ?director dbo:birthDate ?birthDate2 . }
  BIND (COALESCE(?birthDate1, ?birthDate2) AS ?birthDate)
}
LIMIT 100

